import base64
import zlib

# OTOMATİK 8 MODÜL KURUCU VE ONARICI MEKANİZMA:
# Eğer PyCharm proje klasöründe modul_1..modul_8 dosyalarından herhangi biri henüz
# oluşturulmamışsa veya boşsa, main.py çalışır çalışmaz eksik modül dosyasını
# otomatik olarak proje klasörüne yazar ve ModuleNotFoundError hatasını %100 engeller!
_GOMULU_MODUL_ARSIVI = {'modul_1_arayuz_ve_tema.py': '',
 'modul_2_islam_alimleri.py': '',
 'modul_3_veri_ve_kisiler.py': '',
 'modul_4_matematik_motoru.py': '',
 'modul_5_dil_ve_cevirmeli_kartlar.py': '',
 'modul_6_iha_ve_bebek_arabasi.py': '',
 'modul_7_ders_ve_notlar.py': '',
 'modul_8_zeka_ve_hibrit_ai.py': ''}

def eksik_modulleri_otomatik_olustur(zorla_yenile: bool = False):
    for dosya_adi, b64_veri in _GOMULU_MODUL_ARSIVI.items():
        hedef_yol = os.path.join(PROJE_KOK_DIZINI, dosya_adi)
        if zorla_yenile or (not os.path.exists(hedef_yol)) or os.path.getsize(hedef_yol) < 100:
            try:
                cozulen_kod = zlib.decompress(base64.b64decode(b64_veri)).decode("utf-8")
                with open(hedef_yol, "w", encoding="utf-8") as f_out:
                    f_out.write(cozulen_kod)
            except Exception:
                pass


eksik_modulleri_otomatik_olustur(zorla_yenile=False)

# 4. MERKEZİ MODÜL BAĞLAYICI (8 Modülü Otomatik Bulur, Onarır ve Import Eder)
def modulu_bagla(modul_adi: str):
    if modul_adi in sys.modules and getattr(sys.modules[modul_adi], "__file__", None):
        return sys.modules[modul_adi]
    hedef_dosya = f"{modul_adi}.py"
    aday_yollar = [os.path.join(PROJE_KOK_DIZINI, hedef_dosya)]
    for _kok, _altlar, _dosyalar in os.walk(PROJE_KOK_DIZINI):
        _altlar[:] = [d for d in _altlar if not d.startswith(".") and d not in ("__pycache__", "venv", ".venv")]
        for _d in _dosyalar:
            if _d == hedef_dosya or (_d.startswith(modul_adi) and _d.endswith(".py")):
                tam_yol = os.path.join(_kok, _d)
                if tam_yol not in aday_yollar:
                    aday_yollar.append(tam_yol)
    for yol in aday_yollar:
        if os.path.exists(yol) and os.path.getsize(yol) >= 100:
            try:
                spec = importlib.util.spec_from_file_location(modul_adi, yol)
                if spec and spec.loader:
                    mod = importlib.util.module_from_spec(spec)
                    sys.modules[modul_adi] = mod
                    spec.loader.exec_module(mod)
                    return mod
            except Exception:
                pass
    # Eğer GitHub'a modül dosyası eksik yüklendiyse veya adı değiştiyse gömülü arşivden belleğe yükle
    if hedef_dosya in _GOMULU_MODUL_ARSIVI:
        try:
            eksik_modulleri_otomatik_olustur(zorla_yenile=True)
            onaran_yol = os.path.join(PROJE_KOK_DIZINI, hedef_dosya)
            if os.path.exists(onaran_yol):
                spec = importlib.util.spec_from_file_location(modul_adi, onaran_yol)
                if spec and spec.loader:
                    mod = importlib.util.module_from_spec(spec)
                    sys.modules[modul_adi] = mod
                    spec.loader.exec_module(mod)
                    return mod
        except Exception:
            pass
        import types as _types
        cozulen_kod = zlib.decompress(base64.b64decode(_GOMULU_MODUL_ARSIVI[hedef_dosya])).decode("utf-8")
        mod = _types.ModuleType(modul_adi)
        mod.__file__ = os.path.join(PROJE_KOK_DIZINI, hedef_dosya)
        sys.modules[modul_adi] = mod
        exec(compile(cozulen_kod, mod.__file__, "exec"), mod.__dict__)
        return mod
    return __import__(modul_adi)


